// Generated by vibelang from src/renderer/platform/files.ts; the migrate flow writes it again with each batch.
export function createDesktopFiles(api, os) {
    const attachmentPaths = new WeakMap();
    const openDirectoryPickerDialog = async (options) => {
        return api.openDirectoryPicker({
            multiple: options?.multiple ?? false,
            title: options?.title,
        });
    };
    const openAttachmentPickerDialog = async (options, onFile) => {
        const result = await api.openFilePicker({
            multiple: options?.multiple ?? false,
            title: options?.title,
            defaultPath: options?.defaultPath,
            extensions: options?.extensions,
        });
        if (!result)
            return;
        try {
            for (const file of result.files) {
                const selected = new File([await api.readPickedFile(result.token, file.path)], file.name);
                attachmentPaths.set(selected, file.path);
                await onFile(selected);
            }
        }
        finally {
            await api.releasePickedFiles(result.token);
        }
    };
    // Only the paths: the token that would let this window read the files is released at once.
    const openFilePathPickerDialog = async (options) => {
        const result = await api.openFilePicker({
            multiple: options.multiple ?? false,
            title: options.title,
            extensions: options.extensions,
        });
        if (!result)
            return null;
        await api.releasePickedFiles(result.token);
        return result.files.map((file) => file.path);
    };
    return {
        openDirectoryPickerDialog,
        openAttachmentPickerDialog,
        openFilePathPickerDialog,
        getPathForFile: (file) => attachmentPaths.get(file) ?? api.getPathForFile(file),
        saveFile: (options, content) => api.saveFile({ title: options.title, defaultPath: options.defaultPath }, content),
        openExternal: (url) => api.openExternal(url),
        openBrowser: (url) => api.openBrowser(url),
        openLocalFile: (url) => api.openLocalFile(url),
        async openPath(path, app) {
            if (os !== "windows") {
                await api.openPath(path, app);
                return;
            }
            const resolvedApp = app ? await api.resolveAppPath(app).catch(() => null) : null;
            await api.openPath(path, resolvedApp ?? undefined);
        },
        async revealPath(path) {
            return api.revealPath(path);
        },
        async readClipboardImage() {
            const image = await api.readClipboardImage().catch(() => null);
            if (!image)
                return null;
            return new File([new Blob([image.buffer], { type: "image/png" })], `pasted-image-${Date.now()}.png`, {
                type: "image/png",
            });
        },
        writeClipboardText(text) {
            return api.writeClipboardText(text);
        },
    };
}
